interface IconProps {
    size?: number;
    className?: string;
}

function Svg({
    size = 16,
    className,
    children,
    fill = "none",
    viewBox = "0 0 16 16",
}: IconProps & {
    children: React.ReactNode;
    fill?: string;
    viewBox?: string;
}) {
    return (
        <svg
            width={size}
            height={size}
            viewBox={viewBox}
            fill={fill}
            stroke="currentColor"
            strokeWidth={1.4}
            strokeLinecap="round"
            strokeLinejoin="round"
            className={className}
            aria-hidden="true">
            {children}
        </svg>
    );
}

const makeSvgIcon = (children: React.ReactNode, opts?: { fill?: string; viewBox?: string }) =>
    function Icon({ size, className }: IconProps) {
        return (
            <Svg size={size} className={className} {...opts}>
                {children}
            </Svg>
        );
    };

